-- 2222 🏋️ Exercises from the book "spanish-football-federation-coaching-program-u9-12" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'spanish-football-federation-coaching-program-u9-12');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Dribble circuit with direction changes', 'technical', 'unopposed', NULL, 16, 16, NULL, NULL, 'Run with the ball flat out, brake near a cone, then turn and accelerate again.', '25x25 yd square with a zigzag of red cones; 12 players each with a ball, 7 on the red cones and the rest queued at a yellow start gate.', 'Each player drives at top speed to the next cone, slows as they arrive, changes direction and sprints with the ball to the following cone until the finish line; continuous for 2 minutes then rest.', NULL, 'On the coach''s call everyone turns round: finish becomes start and vice versa.', 'Laces (outer instep) for speed; control the ball when slowing.', '12 players, 1 ball each', 12, 12, '25 x 25 yards', 22.9, 22.9, 8.0, false, false, false, 'U9-U12', 10),
  ('Run with ball between 3-3-1 positions', 'technical', 'unopposed', NULL, 17, 17, NULL, NULL, 'Running with the ball at speed to and from team positions on the pitch.', 'Half a youth pitch with cones laid out as the 3-3-1 (8v8) shape: 2 players on each central cone, 1 on each wide cone; 12 players, 4 balls.', 'Four balls start together from the central cones; each carrier dribbles to the next cone in the sequence, hands the ball over and stays there, so the circuit flows 1-2-3-4-5-6-7 and back.', NULL, 'Change the sequence and allow direction changes on a coach signal; add a pass or two into the sequence.', NULL, '12 players', 12, 12, 'half youth pitch', NULL, NULL, 8.0, false, false, false, 'U9-U12', 20),
  ('Three team dribble race through pole gates', 'technical', 'unopposed', NULL, 18, 18, NULL, NULL, 'Ball mastery with different parts of the foot and fast dribbling in a race.', 'Half a youth pitch with 7 pole gates marking a circuit; three teams, every player with a ball.', 'One player from each team dribbles round the circuit as fast as possible, going back for any missed gate; first over the finish line scores for the team. Several groups can race, spaced apart. 4 x 3 minutes, most points wins.', 'A missed gate must be redone; first across the line scores 1.', 'Run it as a relay with players waiting at stages of the circuit; progress to dribbling 2 balls at once.', NULL, '3 teams', NULL, NULL, 'half youth pitch', NULL, NULL, 12.0, false, false, true, 'U9-U12', 30),
  ('Colour call 1v1 dribble race to corners', 'technical', 'opposed', NULL, 19, 19, NULL, NULL, 'Ball mastery, fast dribbling and reaction speed.', 'Square sized to the group; each corner has a line of 4 cones of one colour and a small pole gate or mini goal; 2 players with a ball wait at the central cone.', 'The coach calls two colours; each player picks one of those corners, races there, slaloms the 4 cones and passes through the gate. First to score gets the point.', 'Only the first scorer gets a point.', 'Call one colour so both race to the same goal; 4 players and 2 colours; 4 players racing round all 4 corners in turn.', NULL, '2 players at a time', 2, 4, 'square to suit level', NULL, NULL, 9.0, true, false, true, 'U9-U12', 40),
  ('Number and colour hoop dribble race', 'technical', 'opposed', NULL, 20, 20, NULL, NULL, 'Quick reactions and fast dribbling from a standing start.', '20x20 yd square with coloured hoops scattered in the middle; two teams of 6 on opposite lines, each player numbered and with a ball.', 'Coach calls a number and a colour; the two players with that number react and dribble into a hoop of that colour. First to stop the ball inside scores for their team.', 'First into the right hoop scores 1.', 'Call several numbers and one colour; one number and several colours to visit in order; several numbers and several colours.', NULL, '2 teams of 6', 12, 12, '20 x 20 yards', 18.3, 18.3, 9.0, false, false, true, 'U9-U12', 50),
  ('Read the defender: pass, beat or drive', 'one_v_one', 'opposed', 'in_possession', 21, 21, NULL, NULL, 'Decide by the defender''s position whether to play a one-two, take him on 1v1 or dribble into space at speed.', '15-20 yd square with 8 attackers (2 per corner) and 3 defenders inside.', 'Four players set off at once from the corners with a ball, look up and choose: defender in the middle = one-two with him and dribble on; defender front-on = beat him 1v1; defender close to the side = drive past into space. Defenders switch corners after each action.', NULL, 'On the coach''s signal all players change direction.', 'Look up early to read the defender.', '8 attackers + 3 defenders', 11, 11, '15-20 yard square', 16.5, 16.5, 9.0, false, false, true, 'U9-U12', 60),
  ('Dribble past defender into central square', 'one_v_one', 'opposed', 'in_possession', 22, 22, NULL, NULL, 'Run with the ball at speed accurately and get past an opponent.', '20x20 yd area with a 5x5 yd central square; 8 players in pairs - 4 attackers with a ball in the corners, 4 defenders sitting by cone gates of the central square.', 'Attackers drive at speed towards the defenders and, as they get close, use one change of direction to go past and enter the square. First in scores; if a defender wins the ball, roles swap.', 'First attacker into the square scores 1.', 'Defenders stand instead of sit; attacker uses two changes of direction to beat the defender and dribble through the gate.', NULL, '8 players in pairs', 8, 8, '20 x 20 yards', 18.3, 18.3, 8.0, false, false, true, 'U9-U12', 70),
  ('Lose the shadow while dribbling', 'one_v_one', 'opposed', 'in_possession', 23, 23, NULL, NULL, 'Running with the ball at speed and with control to shake off a marker and keep the ball.', '15x15 yd area, players in pairs, one ball per pair.', 'The ball carrier tries to escape a defender who shadows every move for 30 seconds, then they swap roles. Keeping the ball inside the area for the 30 seconds scores a point.', 'Keep possession in the area for 30 s = 1 point.', 'Defender starts passive and builds up to fully active depending on level.', NULL, 'pairs', NULL, NULL, '15 x 15 yards', 13.7, 13.7, 9.0, false, false, false, 'U9-U12', 80),
  ('Collect the treasure dribbling game', 'one_v_one', 'opposed', 'in_possession', 24, 24, NULL, NULL, 'Fast dribbling and beating a gate defender to collect points.', '25x25 yd area with an inner 20x20 yd square, 4 cone gates each guarded by a white defender and a pile of cones (treasure) in the centre; 2 hoops behind each gate; 4 blue and 4 red players with a ball each.', 'Players dribble inside, pick up a cone, then beat a gate defender and dribble out through the gate to drop the cone in their team''s hoop, repeating for the set time. Most treasure wins; if a defender touches or wins the ball the carrier must try another gate.', 'Team with the most cones at the end wins.', 'Must use a different gate after each collection; must use a change of direction to beat the defender at the gate.', NULL, '4v4 + 4 defenders', 12, 12, '25 x 25 yards', 22.9, 22.9, 10.0, false, false, true, 'U9-U12', 90),
  ('Dribble moves past mannequins in a cycle', 'technical', 'unopposed', NULL, 27, 27, NULL, NULL, 'Rehearse specific moves to beat a defender, then pass.', '15 yd square with cones and two mannequins (or tall cones) as shown; 4 players, 2 balls starting at opposite ends.', 'Player dribbles forward, beats the mannequin with a set move towards the cone on the right, then passes to the opposite end and follows the pass; continuous. Move changes every two minutes: step-over and inside touch away, step-over and outside of other foot, the chop, double step-over.', NULL, 'Perform a second move before passing.', 'Use both sides; speed up the moves as technique improves.', '4 players', 4, 4, '15 x 15 yards', 13.7, 13.7, 9.0, false, false, false, 'U9-U12', 100),
  ('Zonal 1v1 duel into end zone', 'one_v_one', 'opposed', 'in_possession', 28, 28, NULL, NULL, 'Dribble past a defender who has time to set up, with the defender learning when to engage.', '1v1 channels with three 5 yd zones (A-C) plus a 2.5 yd yellow end zone at each end.', 'Attacker dribbles from zone A into B while the defender retreats from B to C to set his body; attacker then tries to beat him in C and dribble into the end zone (1 point). If the defender wins it he dribbles to the opposite end zone (1 point) while the attacker chases. Restart with the attacker; swap roles halfway.', 'Dribble into end zone = 1 point for either player.', NULL, 'Defender picks the moment to contest; attacker shifts ball away at the right time.', 'pairs', NULL, NULL, '3 x 5 yard zones + 2 end zones', NULL, NULL, 9.0, false, false, true, 'U9-U12', 110),
  ('End to end dribble through guarded gate', 'one_v_one', 'opposed', 'in_possession', 29, 29, NULL, NULL, 'Dribble against a front-on defender using direction changes and different moves.', '10x20 yd area with an end zone at each end and a central cone gate guarded by one defender; 2 or more players with a ball at each end.', 'Players dribble from one end zone to the other, using a move to beat the defender and go through the central gate, continuously. If the defender wins the ball or knocks it out he swaps with the player who lost it.', 'Defender who wins the ball swaps roles.', 'Narrow the gate; add a second defender; all moves on the weaker foot.', NULL, '4+ dribblers + 1 defender', 5, NULL, '10 x 20 yards', 18.3, 9.1, 9.0, false, false, true, 'U9-U12', 120),
  ('Bulldog end to end dribbling game', 'one_v_one', 'opposed', 'in_possession', 30, 30, NULL, NULL, 'Dribble past front-on defenders with changes of direction in a continuous game.', 'Groups of 6-8 in a 10x30 yd area with end zones; 2 defenders, the rest with a ball.', 'Dribblers go end zone to end zone scoring a point each time they arrive. A defender who wins the ball or knocks it out scores 2 and swaps roles with the dribbler. Most points wins.', 'Arrive in end zone = 1; defender win = 2 and swap.', 'Teams with equal numbers (e.g. 3 v 3) for 4 minutes each way, compare scores; all moves with the weaker foot.', NULL, 'groups of 6-8', 6, 8, '10 x 30 yards', 27.4, 9.1, 8.0, false, false, true, 'U9-U12', 130),
  ('One minute game: dribble and keep the ball', 'one_v_one', 'opposed', 'in_possession', 31, 31, NULL, NULL, 'Keep dribbling past opponents under constant pressure.', '20x20 yd area, everyone against everyone; e.g. 12 players and 4 balls (start with 4 players on a ball or 4 balls in the middle).', 'Players with a ball try to dribble past opponents and keep it while the rest try to win it. When the minute ends the 4 players with a ball score a point. Play 5-7 games; first to 3 points wins.', 'Holding a ball at the minute = 1 point.', 'Take a ball away after each game; players must keep facing and taking on opponents rather than just shielding.', NULL, '12 players, 4 balls', 8, 16, '20 x 20 yards', 18.3, 18.3, 6.0, false, false, false, 'U9-U12', 140),
  ('1v1 dribble through defended cone gates', 'one_v_one', 'opposed', 'in_possession', 32, 32, NULL, NULL, 'Accurate dribbling with both feet to beat opponents.', '20 yd square with 8 cone gates; 10-12 players, red attackers each with a ball, white defenders guarding the gates.', 'Attackers approach a defender, beat him and dribble through a cone gate to score for their team. A defender who wins the ball scores and swaps roles with the attacker.', 'Through a gate = 1 point; defender win = 1 point and swap.', 'All moves on the weaker foot; defenders keep their legs together to make it easier.', NULL, '10-12 players', 10, 12, '20 yard square', 18.3, 18.3, 9.0, false, false, true, 'U9-U12', 150),
  ('Sprint, receive, beat defender and finish', 'one_v_one', 'opposed', 'in_possession', 33, 33, NULL, NULL, 'Receive and dribble past an opponent quickly to score.', 'Half a youth pitch, 2 goals with goalkeepers, 6 outfield players in 2 teams of 3 starting on opposite sides with poles.', 'Red passes to a goalkeeper, sprints round a pole, changes direction and receives the return pass; the white player has made the mirror run and defends. Red tries to beat him and score (1 point); a defender win or ball out scores 1 for the defender. Teams alternate starting.', 'Goal = 1; defender win = 1.', 'Goal counts double if scored within 7 seconds of receiving without the defender touching the ball; play 2 v 2 with the focus still on dribbling.', NULL, '2 teams of 3 + 2 GKs', 8, 8, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 160),
  ('Number call 1v1 duels to goal', 'one_v_one', 'opposed', 'in_possession', 34, 34, NULL, NULL, 'Quick reactions and dribbling past an opponent in 1v1.', '30x30 yd area, two teams numbered 1-6 in opposite corners, 2 goals with goalkeepers, coach outside with balls.', 'Coach calls a number and throws a ball in; both players race to it and the winner tries to dribble past the other and score. If the defender wins it he attacks the other goal. Ball out = both go back.', NULL, 'Call 2 or 3 numbers with one ball for 2v2 or 3v3, still focused on the carrier dribbling.', NULL, '2 teams of 6 + 2 GKs', 14, 14, '30 x 30 yards', 27.4, 27.4, 12.0, true, true, true, 'U9-U12', 170),
  ('Lose marker, receive and pass back', 'one_v_one', 'opposed', 'in_possession', 37, 37, NULL, NULL, 'Check away from a marker to receive in space.', '10x20 yd area in 3 zones: a passer in zone 1, an empty neutral zone 2 nobody enters, and 1 attacker v 1 defender in the larger zone 3.', 'The attacker checks away from his marker to get free, receives the pass and plays it back to the passer (1 point). The defender tries to intercept or win it (1 point). Change roles after a set time.', 'Return pass to zone 1 = 1; defender win = 1; nobody enters zone 2.', 'Swap roles each time the defender wins the ball.', NULL, '3 players', 3, 3, '10 x 20 yards', 18.3, 9.1, 9.0, false, false, true, 'U9-U12', 180),
  ('Quick 2v1 attack with recovering defender', 'one_v_one', 'overload', 'in_possession', 38, 38, NULL, NULL, 'Exploit a 2v1 quickly before defensive help arrives.', '15x20 yd area with a 5 yd zone at one end and 2 small goals at the other; 2 reds, 1 blue defender plus a second blue in the end zone.', 'Coach feeds the deepest red; the reds try to score fast in either small goal 2v1. The second blue may recover once a red touches the ball, so the first blue delays to buy time for 2v2. Reds get 5 attacks, then swap; most goals wins.', '5 attacks each; most goals wins.', 'If the defenders win it, they dribble into the end zone to score.', 'Attack fast before it becomes 2v2; first defender delays.', '2v1 (+1)', 4, 4, '15 x 20 yards', 18.3, 13.7, 9.0, true, false, true, 'U9-U12', 190),
  ('Three station dribble, shoot and 2v1', 'finishing', 'opposed', 'in_possession', 39, 39, NULL, NULL, 'Dribble at speed, shoot and play a 2v1.', 'Half a youth pitch with 3 stations (A central, B and C wide) and a goal with keeper.', 'On the whistle A dribbles through poles and shoots from the edge of the box; B dribbles round a pole and passes for A to shoot again; C, starting slower, then joins A for a 2v1 against B, who must react to defend. Swap roles when the reds fail to score.', NULL, NULL, 'Defender B must react quickly.', '3 stations + GK', 4, NULL, 'half youth pitch', NULL, NULL, 10.0, true, true, true, 'U9-U12', 200),
  ('One-two, receive and 2v1 to goal', 'one_v_one', 'overload', 'in_possession', 40, 40, NULL, NULL, 'Fast 2v1 play in the final third.', 'Half a youth pitch, 2 teams of 6 starting alternately with a ball, 2 large goals with goalkeepers.', 'Red passes to a goalkeeper, sprints back round a pole and forward; a teammate opposite mirrors the run and a blue does the same at the other end. The keeper returns the ball and the reds attack 2v1, needing to score within 7 seconds (1 point); the blue defends and scores 1 for winning it.', 'Score within 7 seconds = 1; defender win = 1.', 'Make it 2v2 with a player from each team on both sides.', NULL, '2 teams of 6 + 2 GKs', 14, 14, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 210),
  ('2v2 plus neutral game to 4 goals', 'small_sided_game', 'overload', 'in_possession', 41, 41, NULL, NULL, 'Fast 3v2 attacks using a neutral player.', '10x15 yd area, 2 teams of 2 plus 1 yellow neutral, 2 small goals at each end.', 'Coach passes to one pair, who attack with the neutral (3v2) to score in either far goal. When the attack ends (goal, ball out or defenders win it) the coach feeds the other pair, who attack the other way with the neutral.', NULL, 'Add a halfway line: all 3 attackers must be in the attacking half for a goal; both teams can score in any of the 4 goals.', NULL, '2v2+1', 5, 5, '10 x 15 yards', 13.7, 9.1, 10.0, true, false, true, 'U9-U12', 220),
  ('Consecutive 2v1s in two side channels', 'one_v_one', 'overload', 'in_possession', 42, 42, NULL, NULL, 'Fast attacks in 2v1 situations.', '15x20 yd area split into halves lengthways (one blue defender per half) and into two side channels widthways (one red attacker per channel); goal with keeper.', 'Reds start in the right channel and attack 2v1 in the first half, each staying in his channel, aiming to dribble or receive into the second half; then they play another 2v1 against the second defender and try to beat the keeper. If they fail to score, the pair swap with the defenders.', 'Attackers stay in their channel; defenders stay in their half.', 'Each defending pair defends for a set time and scores for every attack stopped.', NULL, '2 attackers, 2 defenders + GK', 5, NULL, '15 x 20 yards', 18.3, 13.7, 10.0, true, true, true, 'U9-U12', 230),
  ('Colour call 2v2 with corner feeders', 'one_v_one', 'opposed', 'in_possession', 43, 43, NULL, NULL, 'Awareness, quick reactions and 2v2 play.', '20x20 yd area with 2v2 inside, 2 goals with keepers and 4 feeders in the corners, each beside a different coloured cone.', 'Coach calls a colour; the attacking pair receive from that feeder and try to score in either goal; they then take a second ball from the same feeder before a new colour is called. 2 balls per corner, 8 in all; count goals, then the pairs swap.', '8 balls per turn; most goals wins.', 'Attackers call the colour themselves for each new ball.', 'Scan to find the called feeder quickly.', '2v2 + 4 feeders + 2 GKs', 10, 10, '20 x 20 yards', 18.3, 18.3, 10.0, true, true, true, 'U9-U12', 240),
  ('Fast 3v2 attack from five cones', 'one_v_one', 'overload', 'in_possession', 44, 44, NULL, NULL, 'Quick combination play and attacking in a 3v2.', 'Half a youth pitch with 5 starting cones, 2 players on each; goal with keeper.', 'A blue on the by-line passes to the central red; the two other reds push up off their cones and two blues step out to defend the 3v2 once the pass is received. Reds finish as fast as they can; blues try to win it. Next group goes; swap roles after a set time.', NULL, 'Start with a pass from an attacker instead.', 'Finish in the shortest possible time.', '3v2 + GK', 6, NULL, 'half youth pitch', NULL, NULL, 10.0, true, true, true, 'U9-U12', 250),
  ('1v1 squares into collective 3v2', 'one_v_one', 'opposed', 'in_possession', 45, 45, NULL, NULL, 'Competitive 1v1 duels that feed a game-like 3v2.', 'Half a youth pitch with 3 red squares and 2 blue squares, each holding a 1v1 pair; large goal with keeper.', 'Pairs play repeated 1v1s in their squares until the coach whistles. The 3 players holding a ball in the red squares break out and attack 3v2 (centre player takes the ball in the middle), while the 2 yellows holding a ball in the blue squares come out to defend the goal.', 'On the whistle, ball holders become the attackers/defenders.', 'Add a square for 4v2 or remove a defensive square for 3v1.', NULL, '10 players + GK', 11, NULL, 'half youth pitch', NULL, NULL, 12.0, true, true, true, 'U9-U12', 260),
  ('Continuous 2v2 with neutral wide players', 'one_v_one', 'overload', 'in_possession', 46, 46, NULL, NULL, 'Fast attacks in 2v2 using support players.', 'Area double a youth penalty box, 2 goals with keepers, 2 teams of 3 pairs, a yellow neutral on each side.', 'Keeper starts; the attacking pair try to score quickly using the two neutrals. If the defenders win it they attack the opposite goal against a new pair coming on, and the old pair leave. After a goal, save or ball out, the keeper at that end restarts with the next two pairs.', NULL, 'Remove the neutral side players for a plain fast 2v2.', 'Use the numerical advantage of the wide neutrals.', '2 teams of 3 pairs + 2 neutrals + 2 GKs', 16, 16, 'double youth penalty box', NULL, NULL, 9.0, true, true, true, 'U9-U12', 270),
  ('Continuous 3v3 four-team duel game', 'small_sided_game', 'opposed', 'in_possession', 47, 47, NULL, NULL, 'Quick 3v3 attacking and defending with constant turnover of teams.', 'Area about twice a youth penalty box with a goal and goalkeeper at each end; 4 teams of 3, two waiting behind each goal line.', 'Keeper feeds 3 attackers who try to score fast against 3 defenders, two of whom must hold hands. If attackers score they get a new ball from the far keeper and attack the other way while a fresh team comes on to defend; if defenders win it they attack and the attackers go off.', 'Two defenders hold hands. Save or ball out of play: keeper restarts and both teams swap out for the next two.', 'Drop the hand-holding when goals come easily.', NULL, '4 teams of 3 + 2 GKs', 12, 14, 'double a youth penalty box', NULL, NULL, 15.0, true, true, true, 'U9-U12', 280),
  ('Dribble and one-two passing square', 'passing_unopposed', 'unopposed', NULL, 51, 51, NULL, NULL, 'Short passing and one-twos while moving.', 'Square sized to age; 10-12 players, one player at each of the two non-start corners (B and C) plus queues at two opposite start corners.', 'From both starts at once, A dribbles up, plays a one-two with B who steps off the cone, then passes ahead for C to run onto; C dribbles to the next start corner and hands over. Coach switches direction.', 'Start with 2 balls, can go up to 3-4.', 'Pass to the next start player instead of dribbling all the way; limit to 1-2 touches.', NULL, '10-12', 10, 12, 'square to suit age/level', NULL, NULL, 10.0, false, false, false, 'U9-U12', 290),
  ('Pairs keep-ball vs hand-holding defenders', 'possession', 'opposed', 'in_possession', 52, 52, NULL, NULL, 'Pass and receive in pairs to keep the ball away from opponents.', '20-30 yard square, 7 pairs; attacking pairs have a ball each, defending pairs hold hands.', 'Attacking pairs pass to each other to keep their ball; defending pairs hunt balls and swap roles with the pair they win it from. Games last 1 minute.', 'Pairs holding a ball at the end of the minute score 1; first pair to 3 points wins.', 'Limit to 2-3 touches; defenders no longer hold hands.', NULL, '7 pairs (14)', 14, 14, '20-30 yard square', 22.9, 22.9, 9.0, false, false, false, 'U9-U12', 300),
  ('Pairs passing through guarded cone gates', 'passing_opposed', 'opposed', 'in_possession', 53, 53, NULL, NULL, 'Combining in pairs to get the ball past a defender.', 'Area to suit age with 6 large cone gates about 5 yards wide; 3 teams of 4, each with 2 gate defenders and an attacking pair.', 'Attacking pairs move round the area and score a point by getting the ball through a gate for the partner to collect, with a straight pass or a one-two. A defender who wins it or knocks it out swaps with his teammate pair into attack.', '1 point per gate completed.', 'On the whistle all pairs change direction; further limits (cut off).', NULL, '3 teams of 4', 12, 12, 'to suit age/level; 5 yard gates', NULL, NULL, 7.0, false, false, true, 'U9-U12', 310),
  ('One-two circuit at different angles', 'passing_unopposed', 'unopposed', NULL, 54, 54, NULL, NULL, 'Passing and receiving from varying angles through repeated one-twos.', 'Area to suit age; 7 players on cones/poles around the area, everyone else with a ball at the start.', 'Each ball player plays a one-two with every station player in order, then dribbles through a cone gate back to the start. Station players step off their cone to pass on the move.', 'Start with 2 touches, move to 1 touch.', 'Swap roles after each 3-minute run.', NULL, '7 stations + rest', NULL, NULL, 'to suit age/level', NULL, NULL, 12.0, false, false, false, 'U9-U12', 320),
  ('Y-shape passing with one-twos', 'passing_unopposed', 'unopposed', NULL, 55, 55, NULL, NULL, 'Fast passing, receiving and movement in a tight space.', '20 yard square with a Y shape of cones or mannequins; at least 6 players, B, C and D by the mannequins, rest at the start.', 'A plays a one-two with B, passes to C and takes B''s spot; B turns to get C''s return, C goes on to the next cone; D comes off his cone to receive from C and passes back to the next starter. Everyone rotates on one place.', NULL, 'Players check away from the cone before coming to receive.', NULL, '6+', 6, NULL, '20 yard square', 18.3, 18.3, 10.0, false, false, false, 'U9-U12', 330),
  ('Double square short and long passing', 'passing_unopposed', 'unopposed', NULL, 56, 56, NULL, NULL, 'Mixing short and long passes round a two-square circuit.', '30 yard outer square and 15 yard inner square; a player at every corner of both plus one extra at each of two start corners; 2 balls.', 'Outer player passes short to the inner player, who comes off his cone and plays long to the next outer player, who plays short to the next inner, who passes to the next start. Everyone follows their pass.', NULL, 'Long pass along the ground and next pass 1 touch; long pass in the air and receiver uses control plus pass.', NULL, '10', 10, NULL, '30 yd outer, 15 yd inner square', 27.4, 27.4, 8.0, false, false, false, 'U9-U12', 340),
  ('Double square one-two, pass and follow', 'passing_unopposed', 'unopposed', NULL, 57, 57, NULL, NULL, 'Quick one-twos with inside players around a circuit.', '30 yard outer and 15 yard inner square; 6 outside players at corners (2 at each start), 4 inside players, one in the middle of each inner side; 2 balls.', 'Outside player carries forward, passes to an inside player and gets it straight back, then passes to the next outside player, who repeats with the next inside player and passes to the start. Outside players rotate after their second pass; inside players stay, so swap roles often.', NULL, 'Start on 2 touches then 1 touch.', NULL, '10', 10, NULL, '30 yd outer, 15 yd inner square', 27.4, 27.4, 9.0, false, false, false, 'U9-U12', 350),
  ('Outside one-two with inside lay-off', 'passing_unopposed', 'unopposed', NULL, 58, 58, NULL, NULL, 'One-twos wide plus a lay-off from a central player for a supporting run.', 'Half a youth pitch with a central square; 12-14 players, 2 balls starting from opposite corners, poles for B, central players C.', 'A dribbles and passes to B, who comes off the pole and returns it; A then plays into C, who lays it off for B arriving on the run. B dribbles on to the next start; A takes B''s place, C switches diagonally after passing.', NULL, 'Change direction on the whistle; add an action like a jump before each receive.', NULL, '12-14', 12, 14, 'half a youth pitch', NULL, NULL, 10.0, false, false, false, 'U9-U12', 360),
  ('1v1 channel build-up and switch game', 'positional_game', 'opposed', 'in_possession', 59, 59, NULL, NULL, 'Building from the back with passing and switches of play.', 'Half a youth pitch split into 3 equal channels, a 1v1 in each and a small goal at the end of each; red keeper starts with the ball in the middle channel.', 'Keeper passes to a red in any channel; reds build up and score in a small goal but cannot leave their channel and all three must touch the ball first. If a blue wins it, all blues may cross channels to counter while reds stay in lanes.', 'All 3 attackers touch the ball before a goal; reds stay in channels.', 'Let blues move freely across channels when defending.', NULL, '3v3 + GK', 7, 7, 'half a youth pitch', NULL, NULL, 15.0, true, true, true, 'U9-U12', 370),
  ('Three-zone 8v8 forward passing game', 'small_sided_game', 'overload', 'in_possession', 60, 60, NULL, NULL, 'Passing forward from build-up through to a finish.', '8v8 in 3 equal zones: GK + 3 red defenders v 1 blue forward, 3v3 midfield, 1 red forward v 3 blue defenders + GK.', 'Play starts from the red keeper and works through the zones to score. Each time, one red can step into the next zone by running on to receive, making 4v3 in midfield and 2v3 up front.', 'Defending team stays in their zones.', 'Set a number of passes in a zone before playing forward.', NULL, '8v8', 16, 16, NULL, NULL, NULL, 15.0, true, true, true, 'U9-U12', 380),
  ('5v1 rondo, one ball feet one hands', 'rondo', 'overload', 'in_possession', 63, 63, NULL, NULL, 'Quick passing under pressure and concentration with two balls.', '5 x 10 yard area, 4-5 outside players and 1 defender inside; 2 balls.', 'One ball is passed on the ground with feet, the other thrown through the air with hands, both kept away from the defender. Defender can use hands only on the thrown ball; whoever loses a ball swaps in.', NULL, 'Start 4 players and 1 ball, build to 5 and 2; on the whistle the balls swap (feet ball becomes thrown and vice versa).', NULL, '5v1', 5, 6, '5 x 10 yards', 9.1, 4.6, 8.0, false, false, false, 'U9-U12', 390),
  ('5v2 rondo, passer switches sides', 'rondo', 'overload', 'in_possession', 64, 64, NULL, NULL, 'Quick passing under pressure with movement after the pass.', '5 x 10 yard area, 5 outside, 2 defenders; two attackers share one side.', 'Normal 5v2; when one of the two players on the shared side passes, he must run to the opposite side.', 'The two on the same side may not pass to each other; max 2 touches.', 'Touch and a half (2 touches forces the next to 1); then all 1 touch.', NULL, '5v2', 7, 7, '5 x 10 yards', 9.1, 4.6, 8.0, false, false, false, 'U9-U12', 400),
  ('4+1 v 2 rondo, inside player rotates', 'rondo', 'overload', 'in_possession', 65, 65, NULL, NULL, 'Passing, receiving in space and finding the inside player.', '10 x 10 yard square, a red on each side plus 1 red inside, 2 defenders inside.', 'Reds keep the ball looking to find the inside player, who keeps moving to offer a line. When he receives and passes out, he and that outside player swap places.', 'Unlimited touches.', 'All reds follow every pass, constantly swapping; then 2 touches max.', NULL, '5v2', 7, 7, '10 x 10 yards', 9.1, 9.1, 8.0, false, false, false, 'U9-U12', 410),
  ('5v2 rondo, hit the middle cone', 'rondo', 'overload', 'in_possession', 66, 66, NULL, NULL, 'Keeping the ball and finding the moment to strike a central target.', '10 yard square, 5-6 outside reds, 2 defenders, a large cone in the centre.', 'Reds keep possession and also try to hit the central cone whenever it is on; defenders must intercept and protect the cone. Swap defenders after a set time or number of wins.', 'Set number of consecutive passes = 1 point; hitting the cone = 2 points.', 'Add a second cone to defend; more (cut off).', 'Defenders talk and work together to close passing angles and the path to the cone.', '5v2 or 6v2', 7, 8, '10 yard square', 9.1, 9.1, 10.0, false, false, false, 'U9-U12', 420),
  ('4v2 rondos with speed stations', 'rondo', 'overload', 'in_possession', 67, 67, NULL, NULL, 'Keep-ball under pressure combined with speed, agility and coordination work.', '4 areas: two 8 yard rondo squares and two speed/coordination lanes (hurdles, rings, ladders, poles); 4 teams of 2 pairs.', 'Two 4v2 rondos run while two pairs work the speed lanes. A defending pair that wins it moves to the outside; the pair that lost it goes to a speed lane and the pair there comes in to defend.', NULL, NULL, NULL, '16 (4 teams of 4)', 16, 16, '8 yard squares', 7.3, 7.3, 10.0, false, false, false, 'U9-U12', 430),
  ('4v1 rondo switching across 4 squares', 'rondo', 'overload', 'in_possession', 68, 68, NULL, NULL, 'Keep-ball with support play and reacting fast when play moves to a new square.', 'Four 8 yard squares joined together; 6 reds and 2 defenders, start with a 4v1 in one square.', 'A red on the shared edge can receive, turn and pass to a teammate waiting in the next square; all reds but one shift over to make a new 4v1 there, the waiting defender comes in and the other rests.', 'Defender who touches it swaps with a red; after 3-5 switches without a defender touch, a defender becomes an attacker automatically.', 'End players limited to 2 touches when turning to switch, others 1 touch.', NULL, '6v2', 8, 8, 'four 8 yard squares', 14.6, 14.6, 10.0, false, false, false, 'U9-U12', 440),
  ('Three-square 4v1 rondos, loser runs in', 'transition', 'overload', 'to_defend', 69, 69, NULL, NULL, 'Keep-ball under pressure plus quick reaction on losing the ball.', 'Three 8 yard squares, a player on each side; 4v1 rondos in two squares, no defender in the third.', 'In the third square players just keep the ball moving. When a defender wins it he goes to the outside, and the player who lost it takes the bib and sprints to the empty square to defend there. Continuous.', NULL, 'Allow runs into a square that already has a defender for a 4v2; 2 touches max.', NULL, '12 + 2 defenders', 14, 14, '8 yard squares', 7.3, 7.3, 10.0, false, false, false, 'U9-U12', 450),
  ('End-to-end 4+3 v 4 rondo', 'rondo', 'overload', 'in_possession', 70, 70, NULL, NULL, 'Passing and support to move the ball from one end to the other.', '20 x 30 yard area, 2 teams of 4 and 3 neutrals (one each side, one inside); reds have 2 players at each end, blues all inside.', 'Reds with the neutrals keep the ball 7v4, trying to move it end to end and back. If blues win it they go to the ends and reds come inside to defend.', NULL, 'Neutrals repositioned, one at each end (rest cut off).', NULL, '4v4+3', 11, 11, '20 x 30 yards', 27.4, 18.3, 8.0, false, false, true, 'U9-U12', 460),
  ('Keep-ball with defenders added (5v1 to 5v5)', 'possession', 'overload', 'in_possession', 73, 73, NULL, NULL, 'Keeping possession as pressure builds one defender at a time.', 'Square to suit age; reds (5) inside, blues (5) numbered 1-5 outside on one side; coach with balls.', 'Coach passes to reds and blue 1 presses (5v1). Every 5 red passes the next blue enters, up to 5v5.', '5 passes at 5v5 = 2 points; blue win or ball out = 1 point to blues and restart at 5v1. Swap roles halfway.', 'Change the number of passes before the next defender enters.', NULL, '5v5', 10, 10, 'to suit age/level', NULL, NULL, 10.0, false, false, false, 'U9-U12', 470),
  ('Three-team 4+4 v 4 keep-ball', 'possession', 'overload', 'in_possession', 74, 74, NULL, NULL, 'Passing, receiving in space and support in an 8v4.', 'Area to suit age, 3 teams of 4: one team on the outside (one per side), two teams inside; 2 balls.', 'Outside team plus one inside team keep the ball 8v4 against the third team. Rotate team roles after a set time.', 'Outside players 1 touch; team winning the ball most often wins.', 'Defenders form two hand-holding pairs to make it easier.', 'Inside players must offer support quickly because the outside is 1 touch.', '3 teams of 4', 12, 12, 'to suit age/level', NULL, NULL, 12.0, false, false, false, 'U9-U12', 480),
  ('8v6 support play keep-ball', 'possession', 'overload', 'in_possession', 75, 75, NULL, NULL, 'Passing, receiving in space and support play.', 'Area to suit age; reds 8 (4 inside, 4 outside), blues 6 all inside.', 'Coach passes to an inside red; reds aim for a target number of consecutive passes against the blues. Change defenders after a set time.', 'E.g. 8 passes = 1 point; blues win or kick it out = 1 point.', 'Touch and a half; then all 1 touch.', NULL, '8v6', 14, 14, 'to suit age/level', NULL, NULL, 11.0, false, false, false, 'U9-U12', 490),
  ('6v6 keep-ball, passer swaps with outside man', 'possession', 'overload', 'in_possession', 76, 76, NULL, NULL, 'Passing, receiving and switching positions while keeping the ball.', 'Area to suit age, 2 teams of 6: 4 inside and 2 on opposite sides each.', 'From the coach''s pass, the team on the ball uses its two outside players (6v4). Each pass to an outside player scores and the passer and outside player trade places; the outside man can dribble in or pass in.', '1 point per pass to an outside player.', 'Outside players may move around the whole square; defenders hold hands to make it easier.', NULL, '6v6', 12, 12, 'to suit age/level', NULL, NULL, 7.0, false, false, false, 'U9-U12', 500),
  ('Three-team keep-ball to corner zones', 'positional_game', 'overload', 'in_possession', 77, 77, NULL, NULL, 'Keep possession then receive in a target corner zone.', 'Area to suit age with 4 corner zones; 3 teams of 4, one team posted one per side, two teams inside.', 'An outside player feeds an inside team, which plays 8v4 with the outside team, keeps the ball and then tries to receive inside a corner zone. If the defenders win it they attack with the same aim; rotate the outside team in after a set time.', 'Receiving inside a corner zone = 1 point.', 'Players may only enter a corner zone after the pass is played, timing their run (more cut off).', 'Keep moving and supporting the ball carrier.', '3 teams of 4', 12, 12, 'to suit age/level', NULL, NULL, 12.0, false, false, true, 'U9-U12', 510),
  ('Two-zone 5v5+2 transition keep-ball', 'transition', 'overload', 'to_attack', 78, 78, NULL, NULL, 'Possession and quick transition after winning the ball.', 'Area split into 2 equal zones; 2 teams of 5 plus 2 neutrals, all starting in one zone.', 'Team on the ball keeps it 7v5 with the neutrals. When defenders win it they look to pass into the other zone; everyone moves across and they keep it 7v5 there. Losing it before the switch keeps play in that zone.', NULL, 'Leave 1-2 defenders waiting in the other zone so the first zone is 7v4 or 7v3.', NULL, '5v5+2', 12, 12, 'to suit age/level', NULL, NULL, 10.0, false, false, true, 'U9-U12', 520),
  ('Twin 3v3 keep-ball, pass to far keeper', 'positional_game', 'opposed', 'in_possession', 79, 79, NULL, NULL, 'Possession and transition in a fast two-zone game.', '20 x 30 yard area split into two halves with a 3v3 in each, plus 5 yard end zones holding keepers who act as neutrals.', 'Coach plays a ball into each half. The team on the ball strings 5 passes then passes to the keeper at the far end; a clean receive in his zone scores. Defenders who win it attack with the same aim.', 'Max 2 touches; 5 passes then pass to far keeper = 1 point.', 'Coach calls a colour and that team switches halves at once; scorer moves into the zone on that side.', NULL, '6v6 + 2 GKs', 14, 14, '20 x 30 yards', 27.4, 18.3, 8.0, false, true, true, 'U9-U12', 530),
  ('Three-team zonal 5v2 switch game', 'positional_game', 'overload', 'in_possession', 80, 80, NULL, NULL, 'Keep-ball and switching play past a middle zone.', '3 equal zones; 3 teams of 5, two teams in the end zones, the third in the middle.', 'Coach feeds one end team and 2 middle players go across to make 5v2. After 5 passes the ball is switched to the far end team without being cut out by the middle players; 2 middle players then cross to that end. If the middle team wins it they swap with the team that lost it.', '5 passes before switching.', 'Allow or forbid the middle 3 from intercepting the switch; more (cut off).', NULL, '3 teams of 5', 15, 15, 'to suit age/level', NULL, NULL, 10.0, false, false, true, 'U9-U12', 540),
  ('Keep-ball with called-number sprint race', 'possession', 'overload', 'in_possession', 81, 81, NULL, NULL, 'Possession plus quick reactions and speed.', 'Area to suit age with a cone gate on each side; 2 teams of 6 numbered 1-6, plus 2 neutrals.', '8v6 keep-ball from the coach''s pass. Every 30 seconds the coach calls a number: those players run out through a gate, round the pitch and back in through the other gate while the rest play on.', '8-10 passes = 1 point; first back from the race = 1 point; 2 touches max.', 'Touch and a half; then fewer touches.', NULL, '6v6+2', 14, 14, 'to suit age/level', NULL, NULL, 9.0, false, false, false, 'U9-U12', 550),
  ('Heading station circuit with aerial contest', 'warm_up', 'unopposed', NULL, 84, 84, NULL, NULL, 'Controlled heading and jumping to compete in the air.', 'Large area with 8 feeder stations on red cones and a central circle; 16 players (8 feeders with a ball, 8 workers).', 'Workers go round the stations anti-clockwise; each feeder throws up and the worker heads it back. After each station the worker runs to the middle and jumps with a teammate as if challenging for a header, then goes to the next station.', NULL, 'Workers control with the head and volley back; swap roles after 2-3 rounds.', NULL, '16', 8, 16, 'large area', NULL, NULL, 10.0, false, false, false, 'U9-U12', 560),
  ('7v7 hands game, score by header', 'warm_up', 'opposed', NULL, 85, 85, NULL, NULL, 'Heading to pass and finish in a game-like warm-up.', '20 x 20 yard area, 7v7 including keepers, two goals.', 'Players throw and head the ball to each other; goals only count from a header.', 'Max 3 steps holding the ball; defenders cannot block a header with hands unless it has bounced.', 'Goal after 2 headers in a row counts double; pass with feet but still catch and head to finish; play with 2 balls.', NULL, '7v7', 14, 14, '20 x 20 yards', 18.3, 18.3, 15.0, true, true, true, 'U9-U12', 570),
  ('Backwards header relay race', 'technical', 'unopposed', NULL, 86, 86, NULL, NULL, 'Headed control and touch, then dribbling at speed.', '3 teams of 4 in their own channels, standing close in a line facing one way, end zone ahead.', 'First player heads the ball up and back to the next, and so on down the line using only heads; the last one heads it, turns and dribbles into the end zone.', 'First team into the end zone scores 1; unlimited headers each, then 1 each.', 'Zig-zag line so the ball goes backwards on a diagonal.', NULL, '3 teams of 4', 8, 12, NULL, NULL, NULL, 7.0, false, false, true, 'U9-U12', 580),
  ('Consecutive headers team contest', 'technical', 'unopposed', NULL, 87, 87, NULL, NULL, 'Accurate headed passing.', '2 teams, each split in two facing lines.', 'First player self-throws and heads to the teammate opposite, who heads it back; each header goes to the back of his line and the next steps in.', '6 headers in a row = 1 point; first to 10 wins.', 'Sprint to the back of the opposite line after heading; add a passive defender in front of the lines.', NULL, '2 teams', 8, NULL, NULL, NULL, NULL, 8.0, false, false, false, 'U9-U12', 590),
  ('Winning headers at varied heights in threes', 'technical', 'passive', NULL, 88, 88, NULL, NULL, 'Reading the flight of the ball and winning headers under pressure.', 'Groups of 3 in channels, a thrower at one end, a header at the other with a defender in the middle.', 'Thrower varies height and direction; the defender backs in with passive pressure while the header nods it back for the thrower to catch. 1 minute or 4 reps, then rotate.', NULL, 'Defender fully active and tries to head it away; 10 throws as a live contest with a point for each header won.', NULL, 'groups of 3', 3, NULL, NULL, NULL, NULL, 8.0, false, false, false, 'U9-U12', 600),
  ('Resistance run, sprint and headed finish', 'finishing', 'unopposed', NULL, 89, 89, NULL, NULL, 'Strength and sprint work ending with a header at goal.', '40 x 30 yard area in 3 zones (two 10 x 30 side zones with small goals, a 20 x 30 middle zone with a full goal and keeper); throwers by each goal.', 'A: piggyback a teammate 10 yards, sprint 10, head a thrown ball into the small goal. B: run 10 yards against a teammate holding your waist, sprint 10, head past the keeper. C: move 10 yards shoulder-to-shoulder against a partner, sprint 10, head into the small goal. Header becomes thrower, thrower goes to the start.', '1 point per goal.', 'Listed but cut off.', NULL, '3 groups', NULL, NULL, '40 x 30 yards', 36.6, 27.4, 12.0, true, true, true, 'U9-U12', 610),
  ('Heading stations: hands game, hurdle, chip', 'finishing', 'opposed', NULL, 90, 90, NULL, NULL, 'Headed passing and finishing across three stations.', 'Half a youth pitch in 3 zones (A, B, C) with 4 players each; a goal with keeper and a coach with balls.', 'A: 2v2 hands-and-heads game to small goals, goals only by header, defenders may not use hands. B: hurdle jump, sprint into the box and head the coach''s thrown or chipped ball past the keeper. C: pairs, one chips over the goal and the other heads in, 3 tries then swap.', NULL, 'In each group two pairs compete for most goals.', NULL, '12 (3 x 4) + GK', 12, 13, 'half a youth pitch', NULL, NULL, 6.0, true, true, true, 'U9-U12', 620),
  ('Sprint header finish plus 3v3 hands-heads game', 'finishing', 'opposed', NULL, 91, 91, NULL, NULL, 'Headed finishing, alone and in a small game.', 'Two practices side by side: 6 players at a goal (one in goal, rest behind cones) with a coach throwing; and a 3v3 to small goals.', '1: Players sprint in and try to head the coach''s throw past the player in goal; a save or miss means the shooter goes in goal, a goal sends him back to the start. 2: 3v3 throwing and heading, at least one header in the build-up and the goal must be headed.', '3v3: at least 1 header in the move and a headed finish.', 'Player in goal acts as a defender who can intercept (rest cut off).', NULL, '6 + 3v3', 12, 12, NULL, NULL, NULL, 12.0, true, true, true, 'U9-U12', 630),
  ('Headed passes then called break to goal', 'finishing', 'unopposed', NULL, 92, 92, NULL, NULL, 'Headed passing then reacting fast to dribble and score.', '50 x 50 yard area with a goal and keeper at both ends; 30 x 30 square in the middle split into 3 channels with groups of 3 (A and C on the sides, B in the middle).', 'B throws alternately to A and C, who head it back. After 20-30 seconds the coach calls two letters; whichever called player gets the ball first controls it and dribbles flat out to the furthest goal to score. Then rotate who is B.', 'First to score wins a point for his team.', 'The uncalled player can defend to stop other teams scoring.', NULL, 'groups of 3 + 2 GKs', 9, NULL, '50 x 50 yards; 30 x 30 middle square', 45.7, 45.7, 10.0, true, true, true, 'U9-U12', 640),
  ('Two-zone 2v2 heading duels with counters', 'finishing', 'opposed', 'in_possession', 93, 93, NULL, NULL, 'Scoring with headers inside a fast counter-attacking game.', 'Two games side by side, each area split into two equal zones with a 2v2 in each, two neutral wide players and a big goal with keeper at each end.', 'Coach feeds a red in zone one; reds work the ball into a neutral''s hands, then run into zone two where the neutral throws for a headed finish. If the keeper saves or blues win it in zone one, blues counter the other way, dodging the other game.', 'Goals only from headers off the neutral''s throw.', 'One or two defenders may drop in to contest the header, making 2v1 or 2v2 in the final zone.', NULL, '2v2 + 2 neutrals per area, keepers', NULL, NULL, NULL, NULL, NULL, 12.0, true, true, true, 'U9-U12', 650),
  ('Hands and headers 5v5 with wide feeders', 'small_sided_game', 'opposed', 'in_possession', 94, 94, NULL, NULL, 'Passing with the head and finishing with headers.', 'Area about twice a youth penalty box, two goals with keepers, 5v5 plus two neutral wide players.', 'Keeper throws out to a teammate''s head. Attackers move the ball with head and hands; neutrals catch and throw it in to a head. Defenders try to win it and then attack.', 'No two consecutive hand actions: after a throw the next touch must be a header; goals only with the head; defenders may only catch a thrown ball.', 'Pair everyone up man-for-man so each player competes in the air with an opponent.', NULL, '5v5 + 2 neutrals + 2 GK', 12, 14, 'double a youth penalty area', NULL, NULL, 9.0, true, true, true, 'U9-U12', 660),
  ('Three-station dribble and sprint finishing', 'finishing', 'unopposed', NULL, 97, 97, NULL, NULL, 'Dribbling at speed and shooting.', 'Half a youth pitch, three groups of four at cone gates: station A races to two small goals, station B has three balls in an arc in front of a big goal, station C has poles and a cone gate.', 'A: two players race, dribble and shoot into a small goal from a marked zone, first goal counts. B: sprint to a ball and shoot, turn back round a big cone, repeat for all three balls (one with weak foot). C: dribble through poles and a gate, then shoot. Groups count goals and rotate every 3 minutes.', 'At B at least one shot with the weaker foot.', 'All goals with the weaker foot; demand faster execution.', NULL, '3 groups of 4', 12, 12, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 670),
  ('Three-group dribbling and combined finish', 'finishing', 'unopposed', NULL, 98, 98, NULL, NULL, 'Dribbling, turning and finishing.', 'Half a youth pitch, three groups of three at red cone gates with blue cone gates near the box, poles for group C, big goal with keeper.', 'At once: A sprints, turns round a cone, dribbles into the box and shoots after a gate; B runs through a gate and shoots; C zig-zags through poles and two gates then passes across for B''s second shot. Players rotate A to B to C.', NULL, 'A slides across after his shot to block B''s second shot from C''s pass.', NULL, '3 groups of 3', 9, 9, 'half youth pitch', NULL, NULL, 8.0, true, true, true, 'U9-U12', 680),
  ('Over-the-head ball, spin and shoot', 'finishing', 'passive', NULL, 99, 99, NULL, NULL, 'Receiving and shooting after a quick 180 degree turn.', 'Cone gate on each side of the pitch facing a big goal with keeper; one player stands in each gate without a ball.', 'Feeder throws the ball over the gate player''s head and closes him down; he spins, controls, dribbles into the box and shoots. Feeder takes the gate spot, shooter goes to the other side.', NULL, 'Two teams on one side race to 10 goals then switch sides; throw at the player instead of over him so he controls then turns.', NULL, 'groups on both sides + GK', NULL, NULL, NULL, NULL, NULL, 9.0, true, true, true, 'U9-U12', 690),
  ('One-two, open up on the half-turn, shoot', 'finishing', 'unopposed', NULL, 100, 100, NULL, NULL, 'Opening the body to receive and shoot.', 'Half a youth pitch, four cones forming two gates near the arc, six players, big goal with keeper.', 'A passes to B and moves to one side; B reads it and returns the ball into that gate; A opens up, takes it on the half-turn, touches into the box and shoots. A goes to B''s spot, B to A''s.', NULL, 'B presses A after his pass; a second ball between the gates that B dribbles at goal with A defending.', NULL, '6 players + GK', 6, 6, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 700),
  ('Drop, turn round pole, receive and finish', 'finishing', 'unopposed', NULL, 101, 101, NULL, NULL, 'Turning, receiving a diagonal pass and finishing.', 'Two groups by each post with balls; two poles outside the penalty area.', 'On the whistle the front player from each side runs out; the next player in the other group plays him a diagonal pass; he turns round the pole, receives, takes one or two touches into the box and shoots. Shooter switches sides.', '1-2 touches before the shot.', 'Move the poles to change distance and angle; set which foot finishes on each side.', NULL, '2 groups + GK', NULL, NULL, NULL, NULL, NULL, 9.0, true, true, true, 'U9-U12', 710),
  ('Three-player read-the-run combination and shot', 'combination', 'unopposed', 'in_possession', 102, 102, NULL, NULL, 'Reading a teammate''s movement, receiving and shooting.', 'Half a youth pitch, two marked zones: C at top of zone 2, B at end of zone 1, A on the start line, big goal with keeper.', 'B checks to one side, C reads it and moves the opposite way; A passes to C; B makes a second run forward; C feeds B who takes it into the box and shoots. Rotate A to B to C.', NULL, 'C chooses where to receive first and B must react to the opposite side.', NULL, 'groups of 3 + GK', 3, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 720),
  ('Four-player combination with wide supporting run', 'combination', 'unopposed', 'in_possession', 103, 103, NULL, NULL, 'Quick combination ending with a diagonal run and finish.', 'Half a youth pitch, four cones (A central, B on the arc, C and D wide), two extra players at the start, big goal with keeper.', 'A passes to B who sets back to C; C plays across to A stepping forward; D makes a forward diagonal run and A slides him in to shoot inside the box. Rotate A to B to C to D; swap C and D sides after a while.', NULL, 'Two groups at once and count goals; weak-foot goals worth 2.', NULL, '6 players + GK', 6, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 730),
  ('Double one-two finishing from both ends', 'combination', 'unopposed', 'in_possession', 104, 104, NULL, NULL, 'Quick one-two combinations and finishing.', 'Half a youth pitch with a big goal and keeper at both ends, three cones each side (A, B, C), two groups mirroring.', 'Simultaneously at both ends A plays two one-twos in a row with B and C, who step off their cones to set back, then A shoots. Rotate A to B to C; groups switch sides after a set time.', '2 or 3 touches by age and level.', 'Vary the pass order; two balls running each side; whole practice one touch.', 'Receive on the move.', '2 groups + 2 GK', NULL, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 740),
  ('Long run, deep pass, cut back and shoot', 'combination', 'unopposed', 'in_possession', 105, 105, NULL, NULL, 'Accurate passing, movement and finishing.', 'Half a youth pitch with a big goal and keeper at both ends, two poles, two groups working in opposite directions, a ball-less inside player each side.', 'First player passes to the inside player and runs long; the inside player plays deep outside the poles; the runner dribbles round the second pole and cuts back into the middle where the inside player from the other group turns and shoots. Roles rotate continuously.', 'Touches set by age/level, aim for one-touch finishing.', NULL, NULL, '2 groups + 2 GK', NULL, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 750),
  ('3v3 to goals with four wide attackers', 'small_sided_game', 'overload', 'in_possession', 106, 106, NULL, NULL, 'Fast attacks and finishing.', '30 x 40 yard area split into two equal zones, goal and keeper each end; 3v3 inside plus two outside players per team, one each side in their attacking zone.', 'Starts from the keeper; teams attack quickly using their outside players. A goal straight from an outside player''s pass counts double. Swap inside and outside players every 4 minutes or after 3-4 goals.', 'Inside players 2 touches, outside players 1 touch; assist from outside player = double goal.', 'Weak-foot goals count 2; headed goals count 3.', NULL, '3v3 + 4 outside + 2 GK', 12, 12, '30 x 40 yards', 36.6, 27.4, 9.0, true, true, true, 'U9-U12', 760),
  ('One-touch zig-zag passing circuit both ends', 'passing_unopposed', 'unopposed', 'in_possession', 109, 109, NULL, NULL, 'Fast one-touch pass and move.', 'Area to suit age, split in two halves with a big goal and keeper at each end; keeper plus five players each side and a spare player by a blue cone.', 'Both keepers start together with a diagonal pass; the ball zig-zags one touch through the five players until the last one passes into the goal, then runs round to join the other side. Players follow their pass; the waiting player comes in to start again.', 'One touch.', 'Allow 2 touches; fixed positions without following passes.', NULL, '12 + 2 GK', 12, 14, NULL, NULL, NULL, 9.0, true, true, true, 'U9-U12', 770),
  ('Mirrored one-touch combinations, cross-finish', 'combination', 'unopposed', 'in_possession', 110, 110, NULL, NULL, 'Fast one-touch combination play.', 'Half a youth pitch, two groups (red and blue) each with five cones in a pattern, big goal with keeper.', 'Both groups pass cone 1 to 5 and follow their pass; the final ball leads No.5 into space and he crosses to the other group''s No.5 to finish. Groups must work at the same tempo. Next player starts after the 4th or 5th pass.', 'One touch.', 'Add a defender in the box; player 3 defends after setting back to 4.', 'Same speed in both groups.', '2 groups of 5+ + GK', 10, NULL, 'half youth pitch', NULL, NULL, 10.0, true, true, true, 'U9-U12', 780),
  ('Four-player combination, wide run and box arrivals', 'combination', 'unopposed', 'in_possession', 111, 111, NULL, NULL, 'Combination play with different supporting runs into the box.', 'Half a youth pitch, four cone positions A-D around a central area, big goal with keeper.', 'A passes diagonally to B and runs wide; B steps off and plays inside to C; C plays back diagonally to D; D plays deep wide for A, who crosses. B, C and D attack the box after their passes. Rotate positions.', NULL, 'Limit touches; run the sequence from the right side.', NULL, 'groups of 4 + GK', 4, NULL, 'half youth pitch', NULL, NULL, 10.0, true, true, true, 'U9-U12', 790),
  ('Flank lay-off, curved run and cross', 'combination', 'unopposed', 'in_possession', 112, 112, NULL, NULL, 'Wide play with supporting runs and finishing.', 'Half a youth pitch, three start positions on each side, mannequins and a pole near the box, big goal with keeper.', 'A dribbles and passes to B dropping off a mannequin, then runs forward; C comes to take B''s lay-off and dribbles wide while B curls round the pole into the box; C crosses for A or B. Rotate, then the mirrored side repeats.', NULL, 'B from the opposite side steps across to press the receiving B.', NULL, '3 per side + GK', 6, NULL, 'half youth pitch', NULL, NULL, 16.0, true, true, true, 'U9-U12', 800),
  ('Switch high up flank with supporting runs', 'combination', 'unopposed', 'in_possession', 113, 113, NULL, NULL, 'Switching play with supporting runs to finish.', 'Half a youth pitch with cones and mannequins, big goal with keeper; A wide left, B central, C high on the right.', 'A passes inside to B and runs diagonally; C has gone high up the flank and B switches it to him, then curves into the box; C crosses for A or B. Rotate; after 4-5 minutes swap A and C so the cross comes from the left.', NULL, 'Add a defender in the box; vary finishes (strong foot low, weak foot low, volley, header).', NULL, 'groups of 3 + GK', 3, NULL, 'half youth pitch', NULL, NULL, 12.0, true, true, true, 'U9-U12', 810),
  ('Forward lay-off, release wide, cross and finish', 'combination', 'unopposed', 'in_possession', 114, 114, NULL, NULL, 'Combination with a forward''s set and a pass out wide.', 'Half a youth pitch, three set positions (A wide right, B wide left, C central forward), big goal with keeper.', 'A passes to B and advances up the right; C drops and B feeds him, moving forward centrally; C lays off to B who plays wide to A high up; A crosses for B and C running in. Rotate; swap A and B sides after 4-5 minutes.', NULL, 'Add an active defender in the box; goals only from one-touch finishes.', NULL, 'groups of 3 + GK', 3, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 820),
  ('Read the drop, inside movement and shot', 'combination', 'unopposed', 'in_possession', 115, 115, NULL, NULL, 'Combination with inside movement to receive and shoot.', 'Half a youth pitch, four set positions (A central start, B high central, C and D wide by mannequins), big goal with keeper.', 'B drops at an angle and A must pass to that side''s wide player; B sets back to that wide player who comes inside off the mannequin; he plays in front of A who steps up; the opposite wide player runs in behind and A feeds him to shoot. Mirrors if B drops the other way. Rotate positions.', NULL, 'Two teams alternate, most goals wins; weak/strong foot scoring.', NULL, 'groups of 4 + GK', 4, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 830),
  ('Fast support one-two then cross to arrivals', 'combination', 'unopposed', 'in_possession', 116, 116, NULL, NULL, 'Quick combination with fast support, crossing and finishing.', 'Half a youth pitch, four set positions (A central, C high central, B and D wide by mannequins), big goal with keeper.', 'C drops to one side and A passes that way to B; B finds C who sets A; A switches to D on the far side; D plays a one-two with C coming across, then crosses for B and C timing runs into the box. Mirrors if C goes the other way.', NULL, 'Two teams alternate, most goals wins.', NULL, 'groups of 4 + GK', 4, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 840),
  ('Flank combination past a defender, cross and finish', 'combination', 'passive', 'in_possession', 117, 117, NULL, NULL, 'Attacking combination with a supporting run and finish against a defender.', 'Half a youth pitch, cones for four start spots A, B, C and defender D, three players at each, big goal with keeper.', 'A passes across to B and runs out wide while C and D move up; B finds C who has dropped, D defends passively; C controls and plays a weighted pass for A; A crosses for C to finish while D now fully defends. Rotate A to B to C to D; swap sides after 5-6 minutes.', 'Defender passive on the pass to C, fully active on the final shot.', NULL, 'Clean technique to receive and play a controlled pass.', '12 players (3 per spot) + GK', 12, 12, 'half youth pitch', NULL, NULL, 12.0, true, true, true, 'U9-U12', 850),
  ('4v2 keep-ball then counter-attack combination', 'transition', 'overload', 'to_attack', 118, 118, NULL, NULL, 'Winning the ball in the centre and counter-attacking with a quick combination.', 'Central marked area, three mannequins as defenders, big goal with keeper; three teams of four, two playing at a time.', 'Blues try 10 straight passes in a 4v2 in the area (1 point). If the two reds win it they counter via a forward and a wide player, joining in while two blues track back; a goal is 1 point. Then reds wait outside, yellows come in for another 4v2 and blues become the pressing pair with two teammates already in advanced positions.', '10 passes = 1 point; counter goal = 1 point.', NULL, NULL, '3 teams of 4 + GK', 12, 13, NULL, NULL, NULL, 15.0, true, true, true, 'U9-U12', 860),
  ('8v2 zonal build-up from keeper in 3-3-1', 'phase_of_play', 'overload', 'in_possession', 121, 121, NULL, NULL, 'Building up and attacking within a 3-3-1 shape.', 'youth pitch approx 50 x 65 yards (45 x 60 m), split into three zones with a marked middle zone, goals both ends; one blue midfielder confined to the middle zone.', 'Reds start each attack from their keeper and build up on the ground in their 3-3-1, playing four attacks against the zone-bound blue; goals counted, then roles reverse against one red midfielder to find a winner.', 'Defender stays in his zone; rotate him each phase.', 'Coach calls a number 1-3 for a set attacking pattern.', NULL, '8v1+GK', NULL, NULL, '50 x 65 yards', 59.4, 45.7, 9.0, true, true, true, 'U9-U12', 870),
  ('8v3 zonal build-up with quick transition', 'phase_of_play', 'overload', 'in_possession', 122, 122, NULL, NULL, 'Building up in a 3-3-1 plus quick reaction after losing the ball.', 'youth pitch approx 50 x 65 yards (45 x 60 m), two zones with a blue midfielder in one and a blue defender in the other.', 'Same as the 8v2 game, but if a blue wins the ball and finds his teammate the attack ends; if reds win it back first they carry on attacking.', 'Defenders stay in their zones.', 'Coach calls a pattern number 1-3; start from game situations such as a throw-in or a turnover in midfield.', 'Press immediately after losing it.', '8v2+GK', NULL, NULL, '50 x 65 yards', 59.4, 45.7, 9.0, true, true, true, 'U9-U12', 880),
  ('8v4 zonal build-up with pressing forward', 'phase_of_play', 'overload', 'in_possession', 123, 123, NULL, NULL, 'Building up past a pressing forward and zonal defenders.', 'youth pitch approx 50 x 65 yards (45 x 60 m), extra zone added where a blue forward presses the red back three, plus blue midfielder and defender in their zones.', 'Progression of the 8v3: blues end the attack by winning it and passing or shooting; reds can keep attacking if they win it back first.', 'Blues defend only in their own area; all three red defenders must touch the ball.', 'Coach calls a pattern number; start from different game situations.', NULL, '8v3+GK', NULL, NULL, '50 x 65 yards', 59.4, 45.7, 9.0, true, true, true, 'U9-U12', 890),
  ('8v8 zonal build-up with hand-holding defenders', 'phase_of_play', 'opposed', 'in_possession', 124, 124, NULL, NULL, 'Building up against more defenders who are restricted.', 'youth pitch approx 50 x 65 yards (45 x 60 m); one blue forward, two blue pairs holding hands in midfield and one pair in their defensive zone.', 'Progression: reds build up and attack; if blues win the ball the attack is over.', 'Blue pairs must hold hands while defending.', 'Reds get two chances; scoring earns two more attacks, otherwise blues attack; start from game situations.', NULL, '8v8', 16, 16, '50 x 65 yards', 59.4, 45.7, 9.0, true, true, true, 'U9-U12', 900),
  ('8v8 build-up game with touch conditions', 'conditioned_game', 'opposed', 'in_possession', 125, 125, NULL, NULL, 'Building up and attacking against full resistance.', 'youth pitch approx 50 x 65 yards (45 x 60 m), normal 8v8 with no zones, goals and keepers.', 'Play starts from the keeper; coach sets conditions for the attacking team. Score and attack again for a point; if not, the restart goes to the other keeper.', 'Examples: all three defenders touch the ball before a goal; or 2 defenders, 2 midfielders and the forward; or every player touches it.', NULL, NULL, '8v8', 16, 16, '50 x 65 yards', 59.4, 45.7, 9.0, true, true, true, 'U9-U12', 910),
  ('Four-square dribbling and turns circuit', 'technical', 'unopposed', NULL, 129, 129, NULL, NULL, 'Ball mastery and dribbling with both feet, control with turns.', 'Four 10 yard squares, each with a different dribbling station (A-D).', 'A: slalom poles with insides of both feet. B: dribble along cones left foot only one way, right foot back. C: dribble at speed cutting sharply round each cone. D: dribble to a cone, stop with the sole, return, repeat with the next cone.', NULL, 'Closer cones/poles; longer distances and more cones.', NULL, NULL, NULL, NULL, '4 squares of 10 yards', 9.1, 9.1, 6.0, false, false, false, 'U9-U12', 920),
  ('2v2 keep-ball then called agility-finish run', 'conditioning', 'opposed', NULL, 130, 130, NULL, NULL, 'Speed, strength, agility, possession and finishing.', 'Half a youth pitch, three 2v2 areas (pairs of reds and blues), hurdles, poles, speed rings, two small goals and a big goal with keeper.', 'Groups play 2v2 keep-ball until the coach calls a colour; that pair sprints off to: run and head a thrown ball back then agility round poles and finish in a small goal; or jump two low hurdles, sprint to a ball and shoot; or 5 squats, speed rings, slalom and score in a small goal. Then move to the next group.', NULL, NULL, NULL, '3 groups of 2v2 + GK', 12, 13, 'half youth pitch', NULL, NULL, 10.0, true, true, true, 'U9-U12', 930),
  ('Four-station agility circuit into 3v1 attack', 'conditioning', 'overload', 'in_possession', 131, 131, NULL, NULL, 'Speed, agility, passing and finishing in a 3v1.', 'Half a youth pitch, four stations A-D with hurdles, poles and speed rings, big goal with keeper.', 'A jumps three hurdles and runs into the box; B sidesteps through poles, collects a ball and passes wide to C; C hops through rings two-footed, sprints onto the pass and crosses for A or B; D does single-foot ring work then sprints in to defend. Rotate A to B to C to D.', NULL, NULL, NULL, 'groups of 4 + GK', 4, NULL, 'half youth pitch', NULL, NULL, 9.0, true, true, true, 'U9-U12', 940),
  ('Five-player agility circuit into 3v2 duel', 'conditioning', 'overload', 'in_possession', 132, 132, NULL, NULL, 'Speed, agility and attacking in a 3v2.', 'Half a youth pitch, five circuits (A1-A3 reds, B1-B2 blues) with hurdles, poles, speed rings, cones, a small goal and a big goal with keeper.', 'A1 jumps hurdles and shoots; A2 does 5 squats and slaloms poles; A3 sprints cone to cone and slaloms with a ball; B1 does lateral pole work and passes into a small goal; B2 does single-leg ring hops. Then A3 dribbles forward to launch a fast 3v2 against B1 and B2.', 'Reds score = red point, otherwise blue point.', 'Rotate positions A1 to A2 to A3 to B1 to B2.', NULL, '5 players + GK', 5, NULL, 'half youth pitch', NULL, NULL, 20.0, true, true, true, 'U9-U12', 950)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'spanish-football-federation-coaching-program-u9-12') b;
INSERT INTO schema_migrations (filename) VALUES ('2222-exercises-book-spanish-football-federation-coaching-program-u9-12.sql') ON CONFLICT DO NOTHING;
COMMIT;
